import random, math, time
from collections import deque, Counter

def girth(n, edges):
    adj=[set() for _ in range(n)]
    for a,b in edges:
        if a==b or b in adj[a]: return 0
        adj[a].add(b); adj[b].add(a)
    best=10**9
    for s in range(n):
        dist=[-1]*n; par=[-1]*n
        dist[s]=0; q=deque([s])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if dist[v]==-1:
                    dist[v]=dist[u]+1; par[v]=u; q.append(v)
                elif par[u]!=v and par[v]!=u:
                    best=min(best, dist[u]+dist[v]+1)
    return best if best<10**9 else None

def random_graph_degseq(deg, tries):
    n=len(deg)
    stubs=[]
    for i,d in enumerate(deg): stubs += [i]*d
    for _ in range(tries):
        random.shuffle(stubs)
        edges=set(); ok=True
        for i in range(0,len(stubs),2):
            a,b=stubs[i],stubs[i+1]
            if a==b: ok=False; break
            if a>b: a,b=b,a
            if (a,b) in edges: ok=False; break
            edges.add((a,b))
        if ok: yield edges

def has_short_cycle_incremental(n, edges, maxlen=6):
    # shortest cycle <=6? for each edge, distance between endpoints in graph w/o edge <=5
    adj=[set() for _ in range(n)]
    for a,b in edges:
        adj[a].add(b); adj[b].add(a)
    for a,b in edges:
        # bfs from a to b excluding edge depth 5
        dist={a:0}; q=deque([a])
        while q:
            u=q.popleft()
            if dist[u]>=5: continue
            for v in adj[u]:
                if (u==a and v==b) or (u==b and v==a): continue
                if v not in dist:
                    if v==b: return True
                    dist[v]=dist[u]+1; q.append(v)
    return False

